function expand(h){if(!h.chain)return h;const n=h.chain.length,last=`s${n-1}`;
 const lines=['flowchart TD',...h.chain.map(([box],i)=>`  s${i}[${box}]`)],steps=h.chain.map(([,caption],i)=>({caption,draws:i?[`L_s${i-1}_s${i}_0`,`s${i}`]:['s0']}));
 for(let i=1;i<n;i++)lines.push(`  s${i-1} --> s${i}`);
 (h.more||[]).forEach((m,k)=>{const id=`x${k}`;
  if(m.loop!==undefined){const to=`s${m.to??0}`;lines.push(`  ${last} -->${m.loop?`|${m.loop}|`:''} ${to}`);steps.push({caption:m.caption,draws:[`L_${last}_${to}_0`]});}
  else{const from=m.aside!==undefined?`s${m.aside}`:last;lines.push(`  ${id}([${m.box}])`,`  ${from} ${m.aside!==undefined?'-.->':'-->'} ${id}`);steps.push({caption:m.caption,draws:[`L_${from}_${id}_0`,id]});}});
 const words=h.chain.map(([box])=>box.replace(/<br>/g,' ').toLowerCase());
 return {...h,mermaid:lines.join('\n'),steps,alt:h.alt??`A drawn flowchart: ${words.join(', then ')}.`};}
export const drawnHowtos=authored.map(h=>({version:1,button:'Show me how',...expand(h)}));
export const drawnHowto=id=>drawnHowtos.find(h=>h.id===id)??null;
// The how-to a page offers: an exact page, or a page family written with a trailing slash-star.
// An exact page wins over a family, so a page inside a family can have its own how-to.
export const howtoForPage=hash=>{const page=String(hash||'').replace(/^#/,''),at=h=>h.at||[];
 return drawnHowtos.find(h=>at(h).includes(page))??drawnHowtos.find(h=>at(h).some(a=>a.endsWith('/*')&&page.startsWith(a.slice(0,-1))))??null;};
